arguments.command:
python - <<'PY'
import csv
from pymatgen.io.vasp import Poscar
for r in csv.DictReader(open('nlo_pool.csv')):
 if r['candidate_id'] not in ['c014','c015','c016','c017','c018']:continue
 s=Poscar.from_str(r['poscar']).structure
 print(r['candidate_id'])
 for a in s:
  if str(a.specie)=='Se':print(' '.join(f'{n.specie}:{n.nn_distance:.2f}' for n in sorted(s.get_neighbors(a,3.6),key=lambda n:n.nn_distance)[:6]))
PY

